class CrestBaseException : public std::exception {
 protected:
  std::string m_text;
  uint32_t m_type;
  CrestBaseException() : m_text(""), m_type(UNKNOWN_TYPE) { ; }

 public:
  char const *what() const throw() { return m_text.c_str(); }
  uint32_t getType() { return m_type; }
}

